class MessWallet { private double balance; MessWallet(double opening) { if (opening < 0) { balance=0; System.out.println("Negative opening balance changed to 0"); } else balance=opening; } void topUp(double amount) { if (amount <= 0) System.out.println("Top-up rejected"); else balance += amount; } void deduct(double amount) { if (amount > balance) System.out.println("Deduct rejected: insufficient balance"); else balance -= amount; } double getBalance() { return balance; } }
public class MessWalletDemo { public static void main(String[] args) { MessWallet wallet = new MessWallet(500); wallet.topUp(200); System.out.println("Balance after top-up: " + wallet.getBalance()); wallet.deduct(1000); System.out.println("Final balance: " + wallet.getBalance()); } }
